DROP TABLE IF EXISTS `checkout_sessions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `checkout_sessions` (
  `id` int NOT NULL AUTO_INCREMENT,
  `_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `office_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `client_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `payment_customer_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gateway_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `api_credential_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `code` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `external_reference` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `idempotency_key` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `payment_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `amount` int NOT NULL,
  `currency` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'BRL',
  `description` text COLLATE utf8mb4_unicode_ci,
  `success_url` text COLLATE utf8mb4_unicode_ci,
  `cancel_url` text COLLATE utf8mb4_unicode_ci,
  `expires_at` datetime(3) DEFAULT NULL,
  `metadata` json DEFAULT NULL,
  `config` json DEFAULT NULL,
  `changes_history` json DEFAULT NULL,
  `status` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'created',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `checkout_sessions__id_key` (`_id`),
  KEY `checkout_sessions_office_id_idx` (`office_id`),
  KEY `checkout_sessions_client_id_idx` (`client_id`),
  KEY `checkout_sessions_payment_customer_id_idx` (`payment_customer_id`),
  KEY `checkout_sessions_gateway_id_idx` (`gateway_id`),
  KEY `checkout_sessions_api_credential_id_idx` (`api_credential_id`),
  KEY `checkout_sessions_code_idx` (`code`),
  KEY `checkout_sessions_external_reference_idx` (`external_reference`),
  KEY `checkout_sessions_idempotency_key_idx` (`idempotency_key`),
  KEY `checkout_sessions_payment_type_idx` (`payment_type`),
  KEY `checkout_sessions_status_idx` (`status`),
  CONSTRAINT `checkout_sessions_api_credential_id_fkey` FOREIGN KEY (`api_credential_id`) REFERENCES `api_credentials` (`_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `checkout_sessions_client_id_fkey` FOREIGN KEY (`client_id`) REFERENCES `clients` (`_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `checkout_sessions_gateway_id_fkey` FOREIGN KEY (`gateway_id`) REFERENCES `gateways` (`_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `checkout_sessions_office_id_fkey` FOREIGN KEY (`office_id`) REFERENCES `offices` (`_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `checkout_sessions_payment_customer_id_fkey` FOREIGN KEY (`payment_customer_id`) REFERENCES `payment_customers` (`_id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=86 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
