CREATE TABLE `clients` (
  `id` int NOT NULL AUTO_INCREMENT,
  `_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `office_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `customer_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `user_type` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `username` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `password` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `config` json DEFAULT NULL,
  `changes_history` json DEFAULT NULL,
  `status` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `clients__id_key` (`_id`),
  KEY `clients_office_id_idx` (`office_id`),
  KEY `clients_customer_id_idx` (`customer_id`),
  KEY `clients_username_idx` (`username`),
  KEY `clients_status_idx` (`status`),
  CONSTRAINT `clients_office_id_fkey` FOREIGN KEY (`office_id`) REFERENCES `offices` (`_id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
